function dernier(liste: any[]): any {
  return liste[liste.length - 1];
}

solution:
function dernier<T>(liste: T[]): T | undefined {
  return liste[liste.length - 1];
}

function grouperPar<T>(items: T[], cle: (item: T) => string): Record<string, T[]> {
  const groupes: Record<string, T[]> = {};
  for (const item of items) {
    const k = cle(item);
    (groupes[k] ??= []).push(item);
  }
  return groupes;
}

