class Depot {
  elements: any[] = [];
  ajouter(e: any) {
    this.elements.push(e);
  }
}

solution:
class Depot<T extends { id: number }> {
  private elements: T[] = [];

  ajouter(e: T): void {
    this.elements.push(e);
  }

  trouver(id: number): T | undefined {
    return this.elements.find(e => e.id === id);
  }

  tous(): T[] {
    return [...this.elements];
  }
}
